<?php
 namespace Pterodactyl\Console\Commands\Dezerx; use Illuminate\Console\Command; use Pterodactyl\Models\Dezerx\DiscordBot; use Pterodactyl\Services\Dezerx\DiscordBot\Deferral; use Pterodactyl\Services\Dezerx\DiscordBot\BotConfig; use Pterodactyl\Services\Dezerx\DiscordBot\DiscordRest; class SyncDiscordCommands extends Command { protected $signature = 'dezerx:discord-sync {--force : Register the commands even when nothing changed}'; protected $description = 'Bring every Discord bot\'s slash commands in line with the panel settings.'; public function handle(DiscordRest $rest): int { Deferral::fresh(); if (!BotConfig::enabled()) { return 0; } $synced = 0; $failed = 0; DiscordBot::query()->orderBy('id')->each(function (DiscordBot $bot) use ($rest, &$synced, &$failed) { if (!BotConfig::serves($bot)) { return; } $result = $rest->syncCommands($bot, (bool) $this->option('force')); $result['ok'] ? $synced++ : $failed++; }); $this->line("Synced {$synced} bots, {$failed} failed."); return 0; } } 